use n_core::{fetch::kline::Kline,v2::replay::ReplayEvent,v3::ablation::{evaluate_research,EntryMode,Experiment,Policy,ResearchRules}};
fn bar(m:usize,o:f64,h:f64,l:f64,c:f64,short:bool)->Kline{let cv=|p|if short{200.-p}else{p};Kline{datetime:format!("2026-01-05 09:{m:02}:00"),open:cv(o),high:cv(if short{l}else{h}),low:cv(if short{h}else{l}),close:cv(c),volume:1.,hold:1.}}
fn eval_mode(bars:&[Kline],short:bool,profit:bool,confirm:bool)->n_core::v3::ablation::ResultRow{let sign=if short{-1.}else{1.};let mut e=ReplayEvent{symbol:"RB0".into(),direction:if short{"down"}else{"up"}.into(),warning_ts:"2026-01-05 09:45:00".into(),entry:100.,stop:100.-sign*26.,target:100.+sign*50.,risk:26.,tick_size:2.,..Default::default()};e.setup_features.setup_quality=4.;evaluate_research(&e,bars,&[],&Default::default(),Experiment{policy:Policy::OriginalS1,no_follow_bar:None,slip_ticks:1.,fee_ticks:0.},10.,None,ResearchRules{entry_mode:if confirm{EntryMode::CloseConfirmNextOpen}else{EntryMode::Touch},micro_progress_level:Some(100.+sign*10.),micro_rejection_level:Some(100.+sign*8.),micro_profit_only:profit,..Default::default()})}
fn eval(bars:&[Kline],short:bool,profit:bool)->n_core::v3::ablation::ResultRow{eval_mode(bars,short,profit,false)}
#[test]
fn requires_post_fill_close_clear_then_later_rejection_and_next_open(){for short in [false,true]{let b=[bar(46,100.,104.,100.,102.,short),bar(47,108.,114.,108.,112.,short),bar(48,108.,110.,104.,106.,short),bar(49,106.,108.,104.,106.,short)];let a=eval(&b,short,false);assert_eq!(a.evaluation.entry_ts.as_deref(),Some("2026-01-05 09:46:00"));assert_eq!(a.evaluation.exit_ts.as_deref(),Some("2026-01-05 09:49:00"));assert_eq!(a.evaluation.exit_reason.as_deref(),Some("micro_progress_rejected"));assert_eq!(a.evaluation.risk,28.);assert_eq!(a.evaluation.net_amount,Some(20.));let prefix=eval(&b[..3],short,false);assert_ne!(prefix.evaluation.status,"closed");}}
#[test]
fn touching_without_completed_close_clear_does_not_arm(){for short in [false,true]{let b=[bar(46,100.,104.,100.,102.,short),bar(47,108.,114.,104.,108.,short),bar(48,108.,110.,104.,106.,short),bar(49,106.,108.,104.,106.,short)];assert_ne!(eval(&b,short,false).evaluation.status,"closed");}}
#[test]
fn profit_variant_ignores_current_gross_loss_but_any_schedules_exit(){for short in [false,true]{let b=[bar(46,100.,104.,100.,102.,short),bar(47,108.,114.,108.,112.,short),bar(48,108.,110.,98.,100.,short),bar(49,100.,102.,98.,100.,short)];assert_eq!(eval(&b,short,false).evaluation.exit_reason.as_deref(),Some("micro_progress_rejected"));assert_ne!(eval(&b,short,true).evaluation.status,"closed");}}
#[test]
fn no_arming_before_entry_even_if_prices_cross_micro_level(){for short in [false,true]{let b=[bar(46,108.,114.,108.,112.,short),bar(47,102.,106.,100.,104.,short),bar(48,104.,106.,100.,104.,short)];let a=eval_mode(&b,short,false,true);assert_eq!(a.evaluation.entry_ts.as_deref(),Some("2026-01-05 09:47:00"));assert_ne!(a.evaluation.status,"closed");assert_ne!(a.evaluation.exit_reason.as_deref(),Some("micro_progress_rejected"));}}
